package com.investmanager.api.portfoliohistory.xirr;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * Annualized money-weighted return for explicit, externally supplied investor cash flows.
 * This class does NOT infer cash flows from buys/sells or income records: those may be
 * internal portfolio movements. End-of-period portfolio liquidation is an explicit
 * positive terminal flow supplied by the caller, never generated by this calculator.
 * Returns empty if there is no unique bracketed solution or data is insufficient.
 */
public final class XirrCalculator {
    private static final double MIN_RATE = -0.999999999;
    private static final double MAX_RATE = 1_000_000.0;
    private static final int STEPS = 512;
    private static final int BISECTION_STEPS = 160;
    private static final double NPV_TOLERANCE_FACTOR = 1e-11;

    public Optional<BigDecimal> calculate(List<DatedCashFlow> flows) {
        if (flows == null || flows.size() < 2) return Optional.empty();
        if (flows.stream().anyMatch(f -> f == null || f.date() == null || f.amount() == null))
            return Optional.empty();
        List<DatedCashFlow> ordered = flows.stream().filter(f -> f.amount().signum() != 0)
                .sorted(Comparator.comparing(DatedCashFlow::date)).toList();
        if (ordered.size() < 2 || !ordered.get(0).date().isBefore(ordered.getLast().date())
                || ordered.stream().noneMatch(f -> f.amount().signum() < 0)
                || ordered.stream().noneMatch(f -> f.amount().signum() > 0)) return Optional.empty();

        LocalDate origin = ordered.getFirst().date();
        double[] amounts = new double[ordered.size()];
        double[] years = new double[ordered.size()];
        double scale = 0;
        for (int i = 0; i < ordered.size(); i++) {
            amounts[i] = ordered.get(i).amount().doubleValue();
            years[i] = ChronoUnit.DAYS.between(origin, ordered.get(i).date()) / 365.0;
            if (!Double.isFinite(amounts[i])) return Optional.empty();
            scale = Math.max(scale, Math.abs(amounts[i]));
        }
        if (scale == 0) return Optional.empty();
        for (int i = 0; i < amounts.length; i++) amounts[i] /= scale;

        // Scan a logarithmic rate grid for roots. Multiple sign-changing roots are
        // ambiguous and must not be silently resolved by choosing an arbitrary guess.
        double previousRate = MIN_RATE;
        double previousNpv = npv(previousRate, amounts, years);
        Double root = null;
        for (int step = 1; step <= STEPS; step++) {
            double rate = Math.expm1(Math.log1p(MAX_RATE) * step / STEPS
                    + Math.log1p(MIN_RATE) * (STEPS - step) / STEPS);
            double currentNpv = npv(rate, amounts, years);
            if (Double.isFinite(previousNpv) && Double.isFinite(currentNpv)
                    && Math.signum(previousNpv) != Math.signum(currentNpv)) {
                double candidate = bisect(previousRate, rate, previousNpv, amounts, years);
                if (!Double.isFinite(candidate)) return Optional.empty();
                if (root != null && Math.abs(candidate - root) > 1e-7 * Math.max(1, Math.abs(root)))
                    return Optional.empty();
                root = candidate;
            }
            previousRate = rate;
            previousNpv = currentNpv;
        }
        if (root == null || Math.abs(npv(root, amounts, years)) > NPV_TOLERANCE_FACTOR)
            return Optional.empty();
        return Optional.of(BigDecimal.valueOf(root).setScale(10, RoundingMode.HALF_UP));
    }

    private static double npv(double rate, double[] amounts, double[] years) {
        double logBase = Math.log1p(rate);
        double sum = 0;
        for (int i = 0; i < amounts.length; i++) {
            sum += amounts[i] * Math.exp(-years[i] * logBase);
        }
        return sum;
    }

    private static double bisect(double lo, double hi, double flo, double[] amounts, double[] years) {
        for (int i = 0; i < BISECTION_STEPS; i++) {
            double mid = lo + (hi - lo) / 2;
            double fmid = npv(mid, amounts, years);
            if (!Double.isFinite(fmid)) return Double.NaN;
            if (Math.abs(fmid) <= NPV_TOLERANCE_FACTOR || hi - lo <= 1e-13 * Math.max(1, Math.abs(mid)))
                return mid;
            if (Math.signum(fmid) == Math.signum(flo)) { lo = mid; flo = fmid; }
            else hi = mid;
        }
        return lo + (hi - lo) / 2;
    }
}
